// The types of the reference data of the accuracy tests (the tables: data/<group>.hpp, generated by
// generateReferenceData.cpp). Values are double: exact for the inputs and results of float32_t and float64_t.
#pragma once

namespace csLie::testReference {

/// a rotation matrix (row major, exactly representable in the tested precision) and its exact log
struct So3LogCase {
  char const *label;
  double R[9];
  double omega[3];
};

/// a rotation vector (exactly representable in the tested precision) and the exact value of a 3x3 function of it (the
/// exp, the left jacobian or its inverse; row major)
struct So3MatrixCase {
  char const *label;
  double omega[3];
  double M[9];
};

/// an angle (exactly representable in the tested precision) and its exact coefficients of the exp and of the
/// jacobians: A = sin(theta) / theta, B = (1 - cos(theta)) / theta^2, C = (theta - sin(theta)) / theta^3,
/// D = (1 - A / (2 B)) / theta^2, K = A / (2 B)
struct CoeffCase {
  char const *label;
  double theta;
  double A;
  double B;
  double C;
  double D;
  double K;
};

/// roll, pitch, yaw (exactly representable in the tested precision) and the exact rotation
/// rotZ(yaw) rotY(pitch) rotX(roll) (row major)
struct RpyCase {
  char const *label;
  double rpy[3];
  double R[9];
};

/// a se2 algebra vector (x, y, theta; exactly representable in the tested precision) and its exact exp (row major)
struct Se2ExpCase {
  char const *label;
  double xi[3];
  double T[9];
};

/// a SE2 matrix (row major, exactly representable in the tested precision) and its exact log (x, y, theta)
struct Se2LogCase {
  char const *label;
  double T[9];
  double xi[3];
};

/// a S2 tangent vector (exactly representable in the tested precision) and its exact s2Exp
struct S2ExpCase {
  char const *label;
  double delta[2];
  double v[3];
};

/// a vector (exactly representable in the tested precision, unit to its precision) and its exact s2Frame (row major)
struct S2FrameCase {
  char const *label;
  double v[3];
  double R[9];
};

/// v and delta (exactly representable in the tested precision) and the exact s2Oplus(v, delta)
struct S2OplusCase {
  char const *label;
  double v[3];
  double delta[2];
  double w[3];
};

/// v and w (exactly representable in the tested precision) and the exact s2OplusInverse(v, w)
struct S2OplusInverseCase {
  char const *label;
  double v[3];
  double w[3];
  double delta[2];
};

} // namespace csLie::testReference
